{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "math",
      "alternatives": [
        "df['FLOW_DURATION_MILLISECONDS'] >= df['DURATION_IN']"
      ],
      "features": ["FLOW_DURATION_MILLISECONDS", "DURATION_IN"],
      "rationale": "Flow duration must be at least the client-to-server stream duration."
    },
    {
      "id": "R2",
      "category": "math",
      "alternatives": [
        "df['FLOW_DURATION_MILLISECONDS'] >= df['DURATION_OUT']"
      ],
      "features": ["FLOW_DURATION_MILLISECONDS", "DURATION_OUT"],
      "rationale": "Flow duration must be at least the server-to-client stream duration."
    },
    {
      "id": "R3",
      "category": "math",
      "alternatives": [
        "df['MIN_TTL'] <= df['MAX_TTL']"
      ],
      "features": ["MIN_TTL", "MAX_TTL"],
      "rationale": "Minimum TTL cannot exceed maximum TTL."
    },
    {
      "id": "R4",
      "category": "math",
      "alternatives": [
        "df['LONGEST_FLOW_PKT'] >= df['SHORTEST_FLOW_PKT']"
      ],
      "features": ["LONGEST_FLOW_PKT", "SHORTEST_FLOW_PKT"],
      "rationale": "Longest packet must be at least as large as shortest packet."
    },
    {
      "id": "R5",
      "category": "math",
      "alternatives": [
        "df['MIN_IP_PKT_LEN'] <= df['MAX_IP_PKT_LEN']"
      ],
      "features": ["MIN_IP_PKT_LEN", "MAX_IP_PKT_LEN"],
      "rationale": "Minimum IP packet length cannot exceed maximum IP packet length."
    },
    {
      "id": "R6",
      "category": "math",
      "alternatives": [
        "df['SRC_TO_DST_IAT_MIN'] <= df['SRC_TO_DST_IAT_MAX']"
      ],
      "features": ["SRC_TO_DST_IAT_MIN", "SRC_TO_DST_IAT_MAX"],
      "rationale": "Minimum IAT cannot exceed maximum IAT in the same direction."
    },
    {
      "id": "R7",
      "category": "math",
      "alternatives": [
        "df['DST_TO_SRC_IAT_MIN'] <= df['DST_TO_SRC_IAT_MAX']"
      ],
      "features": ["DST_TO_SRC_IAT_MIN", "DST_TO_SRC_IAT_MAX"],
      "rationale": "Minimum IAT cannot exceed maximum IAT in the same direction."
    },
    {
      "id": "R8",
      "category": "math",
      "alternatives": [
        "df['SRC_TO_DST_IAT_MIN'] <= df['SRC_TO_DST_IAT_AVG']"
      ],
      "features": ["SRC_TO_DST_IAT_MIN", "SRC_TO_DST_IAT_AVG"],
      "rationale": "Average IAT must be at least the minimum IAT."
    },
    {
      "id": "R9",
      "category": "math",
      "alternatives": [
        "df['SRC_TO_DST_IAT_AVG'] <= df['SRC_TO_DST_IAT_MAX']"
      ],
      "features": ["SRC_TO_DST_IAT_AVG", "SRC_TO_DST_IAT_MAX"],
      "rationale": "Average IAT cannot exceed the maximum IAT."
    },
    {
      "id": "R10",
      "category": "math",
      "alternatives": [
        "df['DST_TO_SRC_IAT_MIN'] <= df['DST_TO_SRC_IAT_AVG']"
      ],
      "features": ["DST_TO_SRC_IAT_MIN", "DST_TO_SRC_IAT_AVG"],
      "rationale": "Average IAT must be at least the minimum IAT."
    },
    {
      "id": "R11",
      "category": "math",
      "alternatives": [
        "df['DST_TO_SRC_IAT_AVG'] <= df['DST_TO_SRC_IAT_MAX']"
      ],
      "features": ["DST_TO_SRC_IAT_AVG", "DST_TO_SRC_IAT_MAX"],
      "rationale": "Average IAT cannot exceed the maximum IAT."
    },
    {
      "id": "R12",
      "category": "math",
      "alternatives": [
        "df['ICMP_TYPE'] // 256 == df['ICMP_IPV4_TYPE']"
      ],
      "features": ["ICMP_TYPE", "ICMP_IPV4_TYPE"],
      "rationale": "ICMP_TYPE is defined as type*256+code, so integer division by 256 yields the type."
    },
    {
      "id": "R13",
      "category": "math",
      "alternatives": [
        "df['TCP_FLAGS'] >= df['CLIENT_TCP_FLAGS']"
      ],
      "features": ["TCP_FLAGS", "CLIENT_TCP_FLAGS"],
      "rationale": "Cumulative TCP flags include all client flags, so total must be at least client flags."
    },
    {
      "id": "R14",
      "category": "math",
      "alternatives": [
        "df['TCP_FLAGS'] >= df['SERVER_TCP_FLAGS']"
      ],
      "features": ["TCP_FLAGS", "SERVER_TCP_FLAGS"],
      "rationale": "Cumulative TCP flags include all server flags, so total must be at least server flags."
    },
    {
      "id": "R15",
      "category": "math",
      "alternatives": [
        "df['SRC_TO_DST_AVG_THROUGHPUT'] == df['SRC_TO_DST_SECOND_BYTES'] * 8"
      ],
      "features": ["SRC_TO_DST_AVG_THROUGHPUT", "SRC_TO_DST_SECOND_BYTES"],
      "rationale": "Throughput in bps is bytes per second multiplied by 8."
    },
    {
      "id": "R16",
      "category": "math",
      "alternatives": [
        "df['DST_TO_SRC_AVG_THROUGHPUT'] == df['DST_TO_SRC_SECOND_BYTES'] * 8"
      ],
      "features": ["DST_TO_SRC_AVG_THROUGHPUT", "DST_TO_SRC_SECOND_BYTES"],
      "rationale": "Throughput in bps is bytes per second multiplied by 8."
    },
    {
      "id": "R17",
      "category": "math",
      "alternatives": [
        "np.where(df['DURATION_IN'] > 0, df['SRC_TO_DST_SECOND_BYTES'] == df['IN_BYTES'] / (df['DURATION_IN'] / 1000), True)"
      ],
      "features": ["SRC_TO_DST_SECOND_BYTES", "IN_BYTES", "DURATION_IN"],
      "rationale": "Bytes per second equals total bytes divided by duration in seconds (using stream duration)."
    },
    {
      "id": "R18",
      "category": "math",
      "alternatives": [
        "np.where(df['FLOW_DURATION_MILLISECONDS'] > 0, df['SRC_TO_DST_SECOND_BYTES'] == df['IN_BYTES'] / (df['FLOW_DURATION_MILLISECONDS'] / 1000), True)"
      ],
      "features": ["SRC_TO_DST_SECOND_BYTES", "IN_BYTES", "FLOW_DURATION_MILLISECONDS"],
      "rationale": "Bytes per second equals total bytes divided by duration in seconds (using flow duration)."
    },
    {
      "id": "R19",
      "category": "math",
      "alternatives": [
        "np.where(df['DURATION_OUT'] > 0, df['DST_TO_SRC_SECOND_BYTES'] == df['OUT_BYTES'] / (df['DURATION_OUT'] / 1000), True)"
      ],
      "features": ["DST_TO_SRC_SECOND_BYTES", "OUT_BYTES", "DURATION_OUT"],
      "rationale": "Bytes per second equals total bytes divided by duration in seconds (using stream duration)."
    },
    {
      "id": "R20",
      "category": "math",
      "alternatives": [
        "np.where(df['FLOW_DURATION_MILLISECONDS'] > 0, df['DST_TO_SRC_SECOND_BYTES'] == df['OUT_BYTES'] / (df['FLOW_DURATION_MILLISECONDS'] / 1000), True)"
      ],
      "features": ["DST_TO_SRC_SECOND_BYTES", "OUT_BYTES", "FLOW_DURATION_MILLISECONDS"],
      "rationale": "Bytes per second equals total bytes divided by duration in seconds (using flow duration)."
    },
    {
      "id": "R21",
      "category": "math",
      "alternatives": [
        "df['LONGEST_FLOW_PKT'] == df['MAX_IP_PKT_LEN']"
      ],
      "features": ["LONGEST_FLOW_PKT", "MAX_IP_PKT_LEN"],
      "rationale": "Longest packet and maximum IP packet length may be identical measurements."
    },
    {
      "id": "R22",
      "category": "math",
      "alternatives": [
        "df['LONGEST_FLOW_PKT'] >= df['MAX_IP_PKT_LEN']"
      ],
      "features": ["LONGEST_FLOW_PKT", "MAX_IP_PKT_LEN"],
      "rationale": "Longest packet (including headers) must be at least the maximum IP packet length."
    },
    {
      "id": "R23",
      "category": "math",
      "alternatives": [
        "df['SHORTEST_FLOW_PKT'] == df['MIN_IP_PKT_LEN']"
      ],
      "features": ["SHORTEST_FLOW_PKT", "MIN_IP_PKT_LEN"],
      "rationale": "Shortest packet and minimum IP packet length may be identical measurements."
    },
    {
      "id": "R24",
      "category": "math",
      "alternatives": [
        "df['SHORTEST_FLOW_PKT'] >= df['MIN_IP_PKT_LEN']"
      ],
      "features": ["SHORTEST_FLOW_PKT", "MIN_IP_PKT_LEN"],
      "rationale": "Shortest packet (including headers) must be at least the minimum IP packet length."
    },
    {
      "id": "R25",
      "category": "math",
      "alternatives": [
        "(df['NUM_PKTS_UP_TO_128_BYTES'] + df['NUM_PKTS_128_TO_256_BYTES'] + df['NUM_PKTS_256_TO_512_BYTES'] + df['NUM_PKTS_512_TO_1024_BYTES'] + df['NUM_PKTS_1024_TO_1514_BYTES']) <= (df['IN_PKTS'] + df['OUT_PKTS'])"
      ],
      "features": ["NUM_PKTS_UP_TO_128_BYTES", "NUM_PKTS_128_TO_256_BYTES", "NUM_PKTS_256_TO_512_BYTES", "NUM_PKTS_512_TO_1024_BYTES", "NUM_PKTS_1024_TO_1514_BYTES", "IN_PKTS", "OUT_PKTS"],
      "rationale": "Sum of packets in size bins cannot exceed total packets (some packets may be outside bins)."
    },
    {
      "id": "R26",
      "category": "math",
      "alternatives": [
        "~(df['NUM_PKTS_UP_TO_128_BYTES'] > 0) | (df['MIN_IP_PKT_LEN'] <= 128)"
      ],
      "features": ["NUM_PKTS_UP_TO_128_BYTES", "MIN_IP_PKT_LEN"],
      "rationale": "If there is a packet in the smallest bin, the minimum IP length must be within that bin's range."
    },
    {
      "id": "R27",
      "category": "math",
      "alternatives": [
        "~(df['NUM_PKTS_1024_TO_1514_BYTES'] > 0) | (df['MAX_IP_PKT_LEN'] > 1024)"
      ],
      "features": ["NUM_PKTS_1024_TO_1514_BYTES", "MAX_IP_PKT_LEN"],
      "rationale": "If there is a packet in the largest bin, the maximum IP length must be within that bin's range."
    },
    {
      "id": "R28",
      "category": "math",
      "alternatives": [
        "~(df['NUM_PKTS_128_TO_256_BYTES'] > 0) | ((df['MIN_IP_PKT_LEN'] <= 256) & (df['MAX_IP_PKT_LEN'] > 128))"
      ],
      "features": ["NUM_PKTS_128_TO_256_BYTES", "MIN_IP_PKT_LEN", "MAX_IP_PKT_LEN"],
      "rationale": "If there is a packet in the 128-256 bin, min and max IP lengths must be consistent with that bin."
    },
    {
      "id": "R29",
      "category": "math",
      "alternatives": [
        "~(df['NUM_PKTS_256_TO_512_BYTES'] > 0) | ((df['MIN_IP_PKT_LEN'] <= 512) & (df['MAX_IP_PKT_LEN'] > 256))"
      ],
      "features": ["NUM_PKTS_256_TO_512_BYTES", "MIN_IP_PKT_LEN", "MAX_IP_PKT_LEN"],
      "rationale": "If there is a packet in the 256-512 bin, min and max IP lengths must be consistent with that bin."
    },
    {
      "id": "R30",
      "category": "math",
      "alternatives": [
        "~(df['NUM_PKTS_512_TO_1024_BYTES'] > 0) | ((df['MIN_IP_PKT_LEN'] <= 1024) & (df['MAX_IP_PKT_LEN'] > 512))"
      ],
      "features": ["NUM_PKTS_512_TO_1024_BYTES", "MIN_IP_PKT_LEN", "MAX_IP_PKT_LEN"],
      "rationale": "If there is a packet in the 512-1024 bin, min and max IP lengths must be consistent with that bin."
    }
  ]
}
